parsed.api_descriptions:
API_name: calculate_mortgage_payment
Description:
{
  "description": "Provides detailed mortgage and other home financing payment information. It uses the standard mortgage calculation formulas to calculate interest and monthly/annual payments.",
  "required_parameters": [
    {
      "name": "interest_rate",
      "type": "Number",
      "description": "Annual interest rate (in %). For example, a 3.5% interest rate would be 3.5. Cannot exceed 10000."
    }
  ],
  "optional_parameters": [
    {
      "name": "loan_amount",
      "type": "Number",
      "description": "Principal loan amount.",
      "default": "200000"
    },
    {
      "name": "home_value",
      "type": "Number",
      "description": "Total value of the home or asset. Must be greater than downpayment.",
      "default": "0"
    },
    {
      "name": "downpayment",
      "type": "Number",
      "description": "Downpayment on the home or asset. Cannot exceed home_value.",
      "default": "0"
    },
    {
      "name": "duration_years",
      "type": "Number",
      "description": "Duration of the loan in years. Must be between 1 and 10000. If not set, default value is 30 years.",
      "default": "30"
    },
    {
      "name": "monthly_hoa",
      "type": "Number",
      "description": "Monthly homeowner association fees.",
      "default": "0"
    },
    {
      "name": "annual_property_tax",
      "type": "String",
      "description": "Annual property tax owed."
    },
    {
      "name": "annual_home_insurance",
      "type": "Number",
      "description": "Annual homeowner's insurance bill.",
      "default": "0"
    }
  ]
}

