Description:
{
  "description": "Provides astronomical data on thousands of planets and exoplanets discovered in our universe.",
  "required_parameters": [],
  "optional_parameters": [
    {
      "name": "name",
      "type": "String",
      "description": "Name of the planet."
    },
    {
      "name": "min_mass",
      "type": "Number",
      "description": "Minimum mass of the planet in Jupiters (1 Jupiter = 1.898 × 10^27 kg).",
      "default": "0"
    },
    {
      "name": "max_mass",
      "type": "Number",
      "description": "Maximum mass of the planet in Jupiters (1 Jupiter = 1.898 × 10^27 kg).",
      "default": "0"
    },
    {
      "name": "min_radius",
      "type": "Number",
      "description": "Minimum average radius of the planet in Jupiters (1 Jupiter = 69911 km).",
      "default": "0"
    },
    {
      "name": "max_radius",
      "type": "Number",
      "description": "Maximum average radius of the planet in Jupiters (1 Jupiter = 69911 km).",
      "default": "0"
    },
    {
      "name": "min_period",
      "type": "Number",
      "description": "Minimum orbital period of the planet in Earth days.",
      "default": "0"
    },
    {
      "name": "max_period",
      "type": "Number",
      "description": "Maximum orbital period of the planet in Earth days.",
      "default": "0"
    },
    {
      "name": "min_temperature",
      "type": "Number",
      "description": "Minimum average surface temperature of the planet in Kelvin.",
      "default": "0"
    },
    {
      "name": "max_temperature",
      "type": "Number",
      "description": "Maximum average surface temperature of the planet in Kelvin.",
      "default": "0"
    },
    {
      "name": "min_distance_light_year",
      "type": "Number",
      "description": "Minimum distance the planet is from Earth in light years.",
      "default": "0"
    },
    {
      "name": "max_distance_light_year",
      "type": "Number",
      "description": "Maximum distance the planet is from Earth in light years."
    }
  ]
}

