parsed.api_descriptions:
API_name: get_weather_forecast
Description:
{
  "description": "Provides up to 14-day hourly and 15-minute weather forecast data.",
  "required_parameters": [
    {
      "name": "q",
      "type": "String",
      "description": "Query parameter based on which data is sent back. Can be Latitude and Longitude (e.g: 48.8567,2.3508), city name (e.g: Paris), US zip, UK/Canada postal code, metar code (e.g: metar:EGLL), IATA code (e.g: iata:DXB), or IP address (e.g: auto:ip or 100.0.0.1)."
    }
  ],
  "optional_parameters": [
    {
      "name": "days",
      "type": "Number",
      "description": "Number of days of forecast required (up to 14 days).",
      "default": "3"
    }
  ]
}

